"""Persistent isolated EqSat worker; private JSON protocol, no benchmark logic."""
import ast
import json
import sys

import kernel_match as K
import eqsat_ablation as A


def decode(source, declarations):
    # Expressions are generated by egglog's own printer in the parent.
    tree=ast.parse(source);last=tree.body.pop()
    if not isinstance(last,ast.Expr):raise ValueError('missing final expression')
    namespace=dict(declarations)
    exec(compile(tree,'<egglog-term>','exec'),namespace)
    return eval(compile(ast.Expression(last.value),'<egglog-term>','eval'),namespace)


def tree(value):
    return tuple(map(tree,value)) if isinstance(value,list) else value


def prove(request):
    K.configure_matcher(collect_egraph_sizes=request['collect'])
    A.install_linalg_level(K)
    if request['kind']=='scalar':
        # Ablation installation may reset counters; retain the requested sizes.
        K._COLLECT_EGRAPH_SIZES=request['collect']
        left,right=[K._ast_to_term(tree(request[k])) for k in ('left','right')]
        matched=K._equivalent_local(left,right,request['distributivity'])
        return dict(matched=matched,counters=K.matcher_telemetry())
    if request['kind']=='region':
        import region_match.egg as E
        convert=lambda s:decode(s,vars(E))
        left,right=[convert(request[k]) for k in ('left','right')]
        unions=[tuple(map(convert,pair)) for pair in request['unions']]
        facts=[tuple(map(convert,pair)) for pair in request['facts']]
        result=E._check_equal_local(left,right,unions,facts,request['iterations'],request['collect'])
        return dict(result=vars(result))
    raise ValueError('unknown proof kind')


for line in sys.stdin:
    try:
        result=prove(json.loads(line))
    except BaseException as error:
        result=dict(error=type(error).__name__+': '+str(error))
    print(json.dumps(result),flush=True)
